import json,subprocess
root=r'''
import os,re,json,stat,subprocess
from pathlib import Path
out={"source_keys":{},"vault_entries":[],"backup_timers":[],"checks":{},"disk_free_gib":0}
p=Path("/srv/projects/pink-iptv/private/systemd-env")
for file in sorted(p.glob("*.env")):
 keys=[]
 for line in file.read_text(errors="replace").splitlines():
  line=line.strip()
  if not line or line.startswith("#") or "=" not in line:continue
  key=line.split("=",1)[0].removeprefix("export ").strip()
  if re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*",key):keys.append(key)
 out["source_keys"][file.name]=keys
v=Path("/root/project-secrets/PINK-IPTV")
if v.is_dir():
 for a in sorted(v.rglob("*"),key=lambda x:str(x)):
  if len(out["vault_entries"])>=75:break
  if a.is_symlink():continue
  rel=a.relative_to(v)
  if len(rel.parts)>4:continue
  st=a.stat()
  out["vault_entries"].append({"name":str(rel),"kind":"dir" if a.is_dir() else "file","mode":oct(stat.S_IMODE(st.st_mode)),"size":st.st_size if a.is_file() else None})
for cmd,name in [(["systemctl","list-unit-files","--type=timer","--no-pager","--no-legend"],"timers"),(["sudo","-n","-u","postgres","psql","-tAc","SELECT 1"],"postgres_local")]:
 try:
  r=subprocess.run(cmd,stdout=subprocess.PIPE,stderr=subprocess.DEVNULL,text=True,timeout=10)
  if name=="timers":
   out["backup_timers"]=[line.split()[0] for line in r.stdout.splitlines() if any(t in line.lower() for t in ["backup","secret","vault","cofre"])]
  else:out["checks"][name]=(r.returncode==0 and r.stdout.strip()=="1")
 except Exception as e:out["checks"][name]=type(e).__name__
out["disk_free_gib"]=round(__import__("shutil").disk_usage("/srv/projects").free/2**30,2)
print(json.dumps(out,sort_keys=True))
'''
p=subprocess.run(["sudo","-n","python3","-c",root],capture_output=True,text=True,timeout=40)
if p.returncode!=0:
 print(json.dumps({"error":"sudo_private_metadata_failed","code":p.returncode}));raise SystemExit(0)
try:
 print(json.dumps(json.loads(p.stdout),sort_keys=True))
except Exception: print(json.dumps({"error":"non_json_sudo_response","bytes":len(p.stdout)}))
